// 1. Extract Project Constraints from the Notion Trigger
const project = $('Trigger: Sourcing Project Updated').item.json;
const maxBudget = project['properties']['Budget Limit']['number'] || 4000000;
const maxLeadTime = project['properties']['Max Lead Time'] || 200;
const minRisk = project['properties']['Min Risk Score'] || 70;

// 2. Map and Filter Bids (Strict Constraint Enforcement)
const allBids = $input.all().map(item => ({
  vendor: item.json.name,
  cost: item.json.property_total_cost,
  risk: item.json.property_risk_compliance_score,
  leadTime: item.json.property_lead_time_days
}));

const validBids = allBids.filter(bid => 
  bid.cost <= maxBudget && 
  bid.leadTime <= maxLeadTime && 
  bid.risk >= minRisk
);

if (validBids.length === 0) {
  return { json: { error: "No vendors met the minimum project constraints." } };
}

// 3. Normalization Bounds Across Valid Bids
const costs = validBids.map(b => b.cost);
const risks = validBids.map(b => b.risk);
const leadTimes = validBids.map(b => b.leadTime);

const minCost = Math.min(...costs);
const maxCost = Math.max(...costs);
const minRiskVal = Math.min(...risks);
const maxRiskVal = Math.max(...risks);
const minLeadTime = Math.min(...leadTimes);
const maxLeadTimeVal = Math.max(...leadTimes);

// Normalization Helpers (0 to 1 scale)
const getCostEfficiencyScore = (cost) => maxCost === minCost ? 1 : parseFloat(((maxCost - cost) / (maxCost - minCost)).toFixed(3));
const getRiskComplianceScore = (risk) => maxRiskVal === minRiskVal ? 1 : parseFloat(((risk - minRiskVal) / (maxRiskVal - minRiskVal)).toFixed(3));
const getLeadTimeScore = (lt) => maxLeadTimeVal === minLeadTime ? 1 : parseFloat(((maxLeadTimeVal - lt) / (maxLeadTimeVal - minLeadTime)).toFixed(3));

// Unified Evaluation Function for True Cross-Scenario Comparison
const calculateOverallScore = (cost, risk, leadTime) => {
  const cScore = getCostEfficiencyScore(cost);
  const rScore = getRiskComplianceScore(risk);
  const lScore = getLeadTimeScore(leadTime);
  return parseFloat(((cScore * 0.4) + (rScore * 0.4) + (lScore * 0.2)).toFixed(3));
};

// 4. Isolate Best Performers
const costSorted = [...validBids].sort((a, b) => a.cost - b.cost);
const riskSorted = [...validBids].sort((a, b) => b.risk - a.risk);

const bestCostVendor = costSorted[0];
const lowestRiskVendor = riskSorted[0];

// Find Balanced Vendor using composite score
const scoredBids = validBids.map(bid => {
  const score = calculateOverallScore(bid.cost, bid.risk, bid.leadTime);
  return { ...bid, score };
});
const balancedVendor = scoredBids.sort((a, b) => b.score - a.score)[0];

// 5. Build Scenarios with Unified Overall Scores
const scenarios = {
  "Best_Cost": {
    strategy: "Lowest financial impact",
    vendor: bestCostVendor.vendor,
    totalCost: bestCostVendor.cost,
    riskScore: bestCostVendor.risk,
    leadTime: bestCostVendor.leadTime,
    overallScore: calculateOverallScore(bestCostVendor.cost, bestCostVendor.risk, bestCostVendor.leadTime)
  },
  "Lowest_Risk": {
    strategy: "Maximum security & compliance",
    vendor: lowestRiskVendor.vendor,
    totalCost: lowestRiskVendor.cost,
    riskScore: lowestRiskVendor.risk,
    leadTime: lowestRiskVendor.leadTime,
    overallScore: calculateOverallScore(lowestRiskVendor.cost, lowestRiskVendor.risk, lowestRiskVendor.leadTime)
  },
  "Balanced": {
    strategy: "Optimal cost-risk-speed trade-off",
    vendor: balancedVendor.vendor,
    totalCost: balancedVendor.cost,
    riskScore: balancedVendor.risk,
    leadTime: balancedVendor.leadTime,
    overallScore: balancedVendor.score
  }
};

// 6. True Programmatic Optimization Mechanism (Dynamic Winner Selection)
let programmaticWinner = "Best_Cost";
let highestScore = -1;

for (const [key, data] of Object.entries(scenarios)) {
  if (data.overallScore > highestScore) {
    highestScore = data.overallScore;
    programmaticWinner = key;
  }
}

// Output data for LLM and downstream nodes
return { 
  json: { 
    scenarios, 
    constraints: { maxBudget, maxLeadTime, minRisk },
    programmaticWinner
  } 
};

// Grabs the text from either the first workflow (Full_RFx_Document) or the second (text)
const rawText = $input.item?.json?.Full_RFx_Document || $input.first().json.text;
const lines = rawText.split('\n');
let blocks = [];
let currentTable = null;

for (let line of lines) {
  line = line.trim();
  if (!line) continue; // Skip empty lines

  let cleanLine = line.replace(/\*\*/g, '');

  // 1. Check for Table Rows
  if (cleanLine.startsWith('|') && cleanLine.endsWith('|')) {

    // Ignore the markdown separator line (e.g., |---|---|)
    if (cleanLine.replace(/[|\s-]/g, '').length === 0) continue;

    // Split the row into an array of cells and trim spaces
    let cells = cleanLine.split('|').slice(1, -1).map(cell => cell.trim());

    // If we aren't currently building a table, start one
    if (!currentTable) {
      currentTable = {
        object: "block",
        type: "table",
        table: {
          table_width: cells.length,
          has_column_header: true, // Assumes the first row is a header
          has_row_header: false,
          children: []
        }
      };
      blocks.push(currentTable);
    }

    // Add the row to the current table's children
    let row = {
      type: "table_row",
      table_row: {
        cells: cells.map(cellText => [{ type: "text", text: { content: cellText } }])
      }
    };
    currentTable.table.children.push(row);
    continue; // Skip the rest of the loop and move to the next line
  } else {
    // If we hit a normal line of text, close out the table tracker
    currentTable = null;
  }

  // 2. Check for Headers
  if (cleanLine.startsWith('### ')) {
    blocks.push({ object: "block", type: "heading_3", heading_3: { rich_text: [{ type: "text", text: { content: cleanLine.replace('### ', '') } }] } });
  } 
  else if (cleanLine.startsWith('## ')) {
    blocks.push({ object: "block", type: "heading_2", heading_2: { rich_text: [{ type: "text", text: { content: cleanLine.replace('## ', '') } }] } });
  } 
  else if (cleanLine.startsWith('# ')) {
    blocks.push({ object: "block", type: "heading_1", heading_1: { rich_text: [{ type: "text", text: { content: cleanLine.replace('# ', '') } }] } });
  } 

  // 3. Check for Bullet Points
  else if (cleanLine.startsWith('* ') || cleanLine.startsWith('- ')) {
    blocks.push({ object: "block", type: "bulleted_list_item", bulleted_list_item: { rich_text: [{ type: "text", text: { content: cleanLine.substring(2) } }] } });
  } 

  // 4. Default to Paragraphs
  else {
    // Truncates at 1900 characters to prevent API rejection limits
    let chunk = cleanLine.substring(0, 1900);
    blocks.push({ object: "block", type: "paragraph", paragraph: { rich_text: [{ type: "text", text: { content: chunk } }] } });
  }
}

return { json: { blocks: blocks } };

// STOP DUPLICATION: Only process the first item if multiple items come in
if ($runIndex > 0) {
  return [];
}

// 1. Grab the raw markdown text from your AI node
let text = $('AI: Generate Executive Summary').item.json.text; 

// 2. Convert standard Markdown bold (**) into Slack bold (*)
text = text.replace(/\*\*/g, '*');

// 3. Find the table and wrap it in a Slack code block so it renders cleanly
let lines = text.split('\n');
let inTable = false;
let slackText = [];

for (let line of lines) {
  if (line.trim().startsWith('|')) {
    if (!inTable) {
      slackText.push('```'); // Start Slack code block
      inTable = true;
    }
    // Completely strip asterisks from table rows so they don't show as raw text
    slackText.push(line.replace(/\*/g, '')); 
  } else {
    if (inTable) {
      slackText.push('```'); // End Slack code block
      inTable = false;
    }
    slackText.push(line);
  }
}

// Catch to close the block if the text ends exactly on a table
if (inTable) {
  slackText.push('```');
}

return { json: { formatted_slack_text: slackText.join('\n') } };
